/**
 * WISDOM BANK D — advaita_vedanta, samkhya. Compact real entries.
 */

import type { WisdomArchetype } from "./types";

export const WISDOM_ADVAITA: WisdomArchetype[] = [
  { concept: "Brahman — The One Without a Second", tradition: "Advaita Vedanta", source: "Brahma Sutras 1.1.2; Chandogya 6.2.1", explanation: "Advaita's foundational claim: brahman — the absolute — is one without a second. Not one among many, but the only reality. Everything else is appearance, name, and form within it. The teaching is not monotheism but non-duality: no second thing exists at all.", application: "Use the claim as a contemplative hypothesis: in every experience, look for the second thing. The separation between self and world, between self and self, is the appearance to investigate — not to believe or disbelieve, but to look at.", questions: ["Where do I experience a 'second' — a genuine other — and what is it?", "What is the difference between one-with-a-second and one-without-a-second?", "Can I look for the second thing directly, right now?"], references: ["Brahma Sutras 1.1.2", "Chandogya Upanishad 6.2.1", "Mandukya Upanishad"], excerpt: "ekam evadvitiyam — One only, without a second.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana"], domains: ["spirituality", "learning"], tags: ["advaita", "brahman", "non_dual", "one_without_second", "foundation"], difficulty: "advanced", minutes: 8 },
  { concept: "Atman Is Brahman — The Identity", tradition: "Advaita Vedanta", source: "Brihadaranyaka 1.4.10; Mahavakya teaching", explanation: "The Advaita identity: atman (the innermost self) is brahman (the absolute). Not similar, not related, not aspiring — identical. The individual's inmost core and the universe's ground are not two. The Mahavakyas ('thou art that', 'I am brahman') are this identity's direct statements.", application: "The identity is the library's central hypothesis. The application is not belief but testing: act as if the innermost self and the absolute are identical, and observe what changes in fear, desire, and relationship.", questions: ["What is the difference between 'I am like the whole' and 'I am the whole'?", "What would the identity's truth change about today's biggest concern?", "Can the identity be tested, or only believed?"], references: ["Brihadaranyaka Upanishad 1.4.10", "Chandogya Upanishad 6.8.7", "Mandukya Upanishad 2"], excerpt: "ayam atma brahma — This self is brahman.", evidence: "traditional", dimensions: ["spirit"], paths: ["jnana"], domains: ["spirituality"], tags: ["advaita", "atman", "brahman", "identity", "mahavakya", "non_dual"], difficulty: "advanced", minutes: 9 },
  { concept: "Maya — The Appearance of the Many", tradition: "Advaita Vedanta", source: "Brahma Sutras 2.1.14; Shankara's commentaries", explanation: "Maya is the teaching's most misunderstood term: not illusion-as-fake but appearance-as-real-enough. The world is experienced, functional, and consequential — yet not ultimately real as a separate multiplicity. Maya is brahman's creative power, appearing as the many.", application: "Maya's application is the library's epistemology: the world is real enough to act in, unreal enough to suffer for. Hold both — the snake's experience was real, the rope was the reality. Act fully, suffer less.", questions: ["Where am I treating appearance as ultimate — and suffering for it?", "Where am I treating appearance as fake — and becoming careless?", "What is the middle category — real-as-experience, unreal-as-entity?"], references: ["Brahma Sutras 2.1.14", "Shankara, Brahma Sutra Bhashya", "Vivekachudamani 172-180"], excerpt: "The world is experienced, functional, consequential — yet not ultimately real as separate multiplicity.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["learning", "spirituality"], tags: ["advaita", "maya", "appearance", "many", "epistemology", "middle"], difficulty: "advanced", minutes: 9 },
  { concept: "Avidya — Ignorance as Misapprehension", tradition: "Advaita Vedanta", source: "Brahma Sutras 1.1.4; Yoga Sutras 2.5", explanation: "Avidya is not lack of information but active misapprehension: taking the non-self for the self, the transient for the eternal, the impure for the pure. Advaita's diagnosis: suffering is not caused by the world but by the world's misidentification as the self.", application: "The application is the library's core practice: catch the misapprehension in the act. When 'I am angry' arises, note the grammar — anger is experienced; the experiencer is not it. The correction is not effort but accuracy.", questions: ["What am I currently misapprehending as 'me'?", "What is the difference between lack of information and active misapprehension?", "Where is accuracy — not effort — the practice?"], references: ["Brahma Sutras 1.1.4", "Yoga Sutras 2.5", "Vivekachudamani 46-55"], excerpt: "Avidya is taking the non-self for the self, the transient for the eternal.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["learning", "growth"], tags: ["advaita", "avidya", "ignorance", "misapprehension", "misidentification"], difficulty: "intermediate", minutes: 7 },
  { concept: "Adhyaropa-Apavada — The Method of Superimposition and Withdrawal", tradition: "Advaita Vedanta", source: "Shankara's method; Brihadaranyaka commentary", explanation: "Advaita's characteristic method: first superimpose (adhyaropa) — give the appearance a name, a role, a reality for practical purposes; then withdraw (apavada) — reveal the appearance's dependence on the underlying reality. The rope-snake is the classic: first 'snake', then 'rope'.", application: "The method is the library's teaching technology: every concept, role, and self-image is a useful superimposition. The practice is not to refuse superimpositions (impossible) but to know their withdrawal — the rope behind the snake.", questions: ["What superimpositions am I currently living inside?", "What is the withdrawal — the rope behind this snake?", "Can I use a superimposition fully while knowing its withdrawal?"], references: ["Shankara's commentaries", "Brihadaranyaka Upanishad 2.3", "Vivekachudamani 37-38"], excerpt: "First superimpose, then withdraw. The snake, then the rope.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["learning", "growth"], tags: ["advaita", "adhyaropa", "apavada", "superimposition", "withdrawal", "method"], difficulty: "advanced", minutes: 8 },
  { concept: "Vyavaharika and Paramarthika — Two Levels of Truth", tradition: "Advaita Vedanta", source: "Shankara's commentary on Brahma Sutras 2.1.14", explanation: "Advaita's two-truth framework: vyavaharika (the transactional level — where the world works, contracts bind, and practice happens) and paramarthika (the absolute level — where only brahman is). The teaching insists both are real at their level; confusing the levels is the error.", application: "The two levels are the library's operating system: practice at the transactional level (schedules, effort, ethics) while knowing the absolute level (nothing is ultimately gained). Confusing them produces either spiritual bypass or spiritual materialism.", questions: ["At which level am I operating right now — and which level am I confusing it with?", "What is my practice's transactional reality?", "What is its absolute reality?"], references: ["Shankara, Brahma Sutra Bhashya 2.1.14", "Vivekachudamani 228-231"], excerpt: "Two levels of truth — transactional and absolute. Both real; confusion is the error.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["learning", "spirituality"], tags: ["advaita", "vyavaharika", "paramarthika", "two_truths", "levels", "transactional"], difficulty: "advanced", minutes: 9 },
  { concept: "The Drig-Drisya Viveka — Seer and Seen", tradition: "Advaita Vedanta", source: "Attributed to Shankara; Vivekachudamani tradition", explanation: "The discrimination of seer and seen: everything you can observe — body, mind, thought, emotion, even the act of observing — is the seen. The seer is never seen. The text's method: take every candidate for 'self' and show it to be an object; what remains is not an object at all.", application: "The seer-seen discrimination is the library's most portable practice. In any moment, ask: is this candidate for 'me' an object of awareness? If yes, it is seen. The seer is the one asking.", questions: ["What is my current candidate for 'me' — and is it seen?", "What is the difference between the seer and the act of seeing?", "Can the seer be made an object — and what happens when I try?"], references: ["Drig-Drisya Viveka (attributed to Shankara)", "Vivekachudamani 67-72", "Ashtavakra Gita 1.1-1.7"], excerpt: "Everything observable is the seen. The seer is never seen.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["learning", "spirituality"], tags: ["advaita", "drig_drisya", "seer", "seen", "discrimination", "portable"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Three Bodies — Gross, Subtle, Causal", tradition: "Advaita Vedanta", source: "Mandukya Upanishad 3-7; Vivekachudamani 78-85", explanation: "Advaita's map of the self's coverings: the gross body (sthula, physical), the subtle body (sukshma, mind-senses-energy), and the causal body (karana, the seed state of deep sleep). The self is the witness of all three — present in waking, dreaming, and deep sleep, unchanged.", application: "Use the three bodies as a daily subtraction: in any state, ask which body is speaking. The gross body speaks fatigue; the subtle speaks anxiety; the causal speaks blankness. The witness speaks none of these — it attends them.", questions: ["Which body is speaking right now?", "What is the witness's relationship to each body?", "What was aware of my deep sleep?"], references: ["Mandukya Upanishad 3-7", "Vivekachudamani 78-85", "Taittiriya Upanishad 2.1-2.7"], excerpt: "Three bodies — gross, subtle, causal — and the witness of all three.", evidence: "traditional", dimensions: ["body", "thought", "spirit"], paths: ["jnana"], domains: ["learning", "spirituality"], tags: ["advaita", "three_bodies", "gross", "subtle", "causal", "witness", "mandukya"], difficulty: "intermediate", minutes: 8 },
  { concept: "The Five Sheaths — Pancha Kosha", tradition: "Advaita Vedanta", source: "Taittiriya Upanishad 2.1-2.7; Vivekachudamani 67-72", explanation: "The five sheaths (koshas) covering the self: food (annamaya), breath (pranamaya), mind (manomaya), intellect (vijnanamaya), and bliss (anandamaya). Advaita's teaching: the self is not any sheath; the sheaths are the self's coverings, not its substance.", application: "The kosha map is the library's diagnostic tool: when suffering feels total, locate the sheath. Food-sheath problems need food; breath-sheath problems need breath; bliss-sheath absence needs rest, not more striving. Each sheath has its own medicine.", questions: ["Which sheath is loudest in my current difficulty?", "What is that sheath's medicine?", "What is the self, apart from all five coverings?"], references: ["Taittiriya Upanishad 2.1-2.7", "Vivekachudamani 67-72"], excerpt: "Five sheaths — food, breath, mind, intellect, bliss. The self is not any of them.", evidence: "traditional", dimensions: ["body", "thought", "spirit"], paths: ["jnana"], domains: ["health", "learning"], tags: ["advaita", "pancha_kosha", "five_sheaths", "coverings", "diagnostic", "medicine"], difficulty: "intermediate", minutes: 8 },
  { concept: "Turiya — The Fourth State", tradition: "Advaita Vedanta", source: "Mandukya Upanishad 7", explanation: "The Mandukya's fourth state: turiya — not a state among states but the awareness in which waking, dreaming, and deep sleep arise. Described as soundless, intangible, formless, indestructible, serene, non-dual. The three states are its objects; it is their subject.", application: "Turiya is the library's horizon state. The application is not to achieve it (it is never absent) but to recognize it: in every state, the awareness of the state is turiya. The practice is recognition, not acquisition.", questions: ["What was aware of my waking, my dreaming, my deep sleep?", "Is turiya a state to enter or a recognition to make?", "What is the difference between recognition and acquisition?"], references: ["Mandukya Upanishad 7", "Mandukya Karika 1-4", "Vivekachudamani 110-115"], excerpt: "The fourth — soundless, intangible, formless, indestructible, serene, non-dual.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana", "raja"], domains: ["spirituality"], tags: ["advaita", "turiya", "fourth_state", "mandukya", "recognition", "awareness"], difficulty: "advanced", minutes: 9 },
  { concept: "The Mahavakyas — The Four Great Sayings", tradition: "Advaita Vedanta", source: "The four Upanishads", explanation: "The four Mahavakyas — prajnanam brahma (consciousness is brahman, Aitareya), tat tvam asi (thou art that, Chandogya), ayam atma brahma (this self is brahman, Mandukya), aham brahmasmi (I am brahman, Brihadaranyaka). Each is a direct pointer; together they are Advaita's compressed teaching.", application: "Contemplate one Mahavakya per week — not as affirmation but as inquiry. 'Thou art that': what is the 'thou' that remains when every 'this' is subtracted? The Mahavakya is a question disguised as a statement.", questions: ["Which Mahavakya addresses my current question?", "What is the difference between repeating a Mahavakya and inquiring into it?", "Which pointer does my mind most need — and why?"], references: ["Aitareya Upanishad 3.3", "Chandogya Upanishad 6.8.7", "Mandukya Upanishad 2", "Brihadaranyaka Upanishad 1.4.10"], excerpt: "Prajnanam brahma, tat tvam asi, ayam atma brahma, aham brahmasmi.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana"], domains: ["spirituality", "learning"], tags: ["advaita", "mahavakyas", "tat_tvam_asi", "aham_brahmasmi", "pointers", "inquiry"], difficulty: "advanced", minutes: 9 },
  { concept: "Jivanmukta — Liberated While Living", tradition: "Advaita Vedanta", source: "Vivekachudamani 271-280; Bhagavad Gita 2.55-2.72", explanation: "The jivanmukta — one liberated while living. Advaita's behavioral portrait: unaffected by joy and sorrow, like the sky by clouds; acting, speaking, sleeping, waking — but never identified. The teaching's most practical chapter: liberation is not a post-death state but a present conduct.", application: "Use the jivanmukta portrait as the library's behavioral standard: measure progress not by experiences but by conduct — disturbance's duration, identification's grip, action's freedom. The portrait is the practice's proof.", questions: ["What would the jivanmukta's conduct look like in my workplace?", "Which portrait feature is closest to my current behavior?", "Can I measure progress by behavior rather than experience?"], references: ["Vivekachudamani 271-280", "Bhagavad Gita 2.55-2.72", "Ashtavakra Gita 5.1-5.15"], excerpt: "The jivanmukta acts, speaks, sleeps, wakes — but is never identified.", evidence: "traditional", dimensions: ["spirit", "action", "emotion"], paths: ["jnana", "karma"], domains: ["growth", "work"], tags: ["advaita", "jivanmukta", "liberated_living", "conduct", "behavior", "standard"], difficulty: "advanced", minutes: 9 },
  { concept: "Videhamukti — Liberation at the Body's End", tradition: "Advaita Vedanta", source: "Brahma Sutras 4.4; Vivekachudamani 331-340", explanation: "Videhamukti — liberation at the body's falling. Advaita's teaching on the end: for the jivanmukta, the body's end is not an event but a formality — the identification was already dissolved. The remaining prarabdha karma (the body's ongoing momentum) plays out and ends.", application: "The videhamukti teaching is the library's death preparation: the end is not feared because it was never the self's beginning. The application is the present-tense recognition — the dissolution is not future; it is the current practice's direction.", questions: ["What is my current relationship to the body's end?", "What is prarabdha — the momentum still playing out?", "Can I distinguish the self's end from the body's end?"], references: ["Brahma Sutras 4.4.1-4.4.22", "Vivekachudamani 331-340", "Bhagavad Gita 2.20"], excerpt: "For the liberated, the body's end is a formality — the identification was already dissolved.", evidence: "traditional", dimensions: ["spirit", "thought", "emotion"], paths: ["jnana"], domains: ["spirituality", "growth"], tags: ["advaita", "videhamukti", "liberation", "death", "prarabdha", "end"], difficulty: "advanced", minutes: 9 },
  { concept: "Prarabdha Karma — The Momentum That Plays Out", tradition: "Advaita Vedanta", source: "Brahma Sutras 3.3; Vivekachudamani 231-240", explanation: "Prarabdha — the portion of past karma currently bearing fruit, the momentum that continues even after liberation. Advaita's teaching: the jivanmukta still experiences the body's karma — illness, aging, results — but without identification. The arrow has left the bow; the archer is free.", application: "The prarabdha teaching is the library's answer to 'why do bad things happen to free people': momentum. The application is the distinction between experiencing and owning — the fruit is eaten, but the eater is not claimed.", questions: ["What momentum is currently playing out in my life?", "What is the difference between experiencing a result and owning it?", "Can the arrow be watched without the archer being claimed?"], references: ["Brahma Sutras 3.3.1-3.3.50", "Vivekachudamani 231-240", "Yoga Vasistha"], excerpt: "The arrow has left the bow; the archer is free. The fruit is eaten, the eater is not claimed.", evidence: "traditional", dimensions: ["thought", "spirit", "action"], paths: ["jnana"], domains: ["growth", "learning"], tags: ["advaita", "prarabdha", "karma", "momentum", "arrow", "archer"], difficulty: "advanced", minutes: 8 },
  { concept: "Sravana, Manana, Nididhyasana — The Threefold Path", tradition: "Advaita Vedanta", source: "Brihadaranyaka 2.4.5; Vivekachudamani 20-25", explanation: "Advaita's prescribed threefold path: shravana (hearing the teaching from a qualified source), manana (reflecting on it until doubts dissolve), and nididhyasana (contemplating it until it is direct, not intellectual). The three are sequential and all required.", application: "The threefold path is the library's study protocol: read (shravana), reflect (manana), contemplate (nididhyasana). Most spiritual reading stops at the first; the teaching's promise lives in the third.", questions: ["Where is my study stopping — at hearing, reflecting, or contemplating?", "What doubt remains unresolved — and what is its manana?", "What would nididhyasana — direct contemplation — look like for this entry?"], references: ["Brihadaranyaka Upanishad 2.4.5", "Vivekachudamani 20-25", "Brahma Sutras 1.1.4"], excerpt: "Hearing, reflecting, contemplating — the threefold path, all required.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["learning", "spirituality"], tags: ["advaita", "shravana", "manana", "nididhyasana", "threefold_path", "study"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Qualified Teacher — Guru Requirements", tradition: "Advaita Vedanta", source: "Vivekachudamani 25-30; Mundaka 1.2.12", explanation: "Advaita's insistence: the teaching requires a qualified teacher — one established in brahman, versed in the scriptures, compassionate, and without desire for reward. The Mundaka's instruction: approach a learned teacher. The tradition treats self-teaching from books as possible but hazardous.", application: "The library inherits the stance: entries are pointers, not transmissions. The application is the seeker's humility — knowing when text suffices and when a teacher is required, especially for the advanced practices.", questions: ["What is my relationship to a qualified teacher — and what is it to text?", "Where is self-teaching serving me, and where is it protecting me?", "What is the difference between a pointer and a transmission?"], references: ["Mundaka Upanishad 1.2.12", "Vivekachudamani 25-30", "Bhagavad Gita 4.34"], excerpt: "Approach a learned teacher. The text points; the teacher transmits.", evidence: "traditional", dimensions: ["thought", "spirit", "connection"], paths: ["jnana"], domains: ["learning", "spirituality"], tags: ["advaita", "guru", "teacher", "qualified", "transmission", "pointer"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Rope-Snake — Advaita's Central Analogy", tradition: "Advaita Vedanta", source: "Vivekachudamani 37-38; Shankara's commentaries", explanation: "The rope-snake analogy: in dim light, a rope is seen as a snake; fear arises; on closer look, only the rope. The snake was never real — only the rope was. Advaita's claim: the world is the snake; brahman is the rope. The error is real as experience, unreal as entity.", application: "The analogy is the library's most practical non-dual tool. Apply it to any current fear: what is the rope (the actual situation) and what is the snake (the feared story)? Seeing the rope does not deny the situation; it removes the snake.", questions: ["What snake am I seeing right now?", "What is the rope — the actual situation?", "What changes when the snake is seen as never having existed?"], references: ["Vivekachudamani 37-38", "Shankara's Brahma Sutra Bhashya", "Ashtavakra Gita 8.1-8.10"], excerpt: "The rope was never a snake. Seeing the rope, the snake vanishes.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["growth", "learning"], tags: ["advaita", "rope", "snake", "analogy", "error", "fear"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Dream Analogy — The World as Dream", tradition: "Advaita Vedanta", source: "Vivekachudamani 41-45; Mandukya Karika", explanation: "The dream analogy: in dream, the body and world seem real; on waking, they are seen as mind-made. Advaita extends the analogy: waking is the same structure, one dream longer. The dream's precision — real as experience, unreal as entity — is the world's status.", application: "Use the dream analogy as an evening practice: review the day as a dream — vivid, meaningful, and not the self. The review is not dismissal; it is the beginning of accurate seeing.", questions: ["What was today's dream containing?", "What would waking from this dream feel like — and who would wake?", "Can I hold the day as real-as-experience and unreal-as-entity simultaneously?"], references: ["Vivekachudamani 41-45", "Mandukya Karika 1.16-1.18", "Ashtavakra Gita 4.1-4.10"], excerpt: "The world is like a dream — vivid, meaningful, and not the self.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["spirituality", "growth"], tags: ["advaita", "dream", "analogy", "waking", "mind_made", "review"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Pot-Space — The Body as Vessel", tradition: "Advaita Vedanta", source: "Vivekachudamani 55-60; Yoga Vasistha", explanation: "The pot-space analogy: the space inside a pot is not the pot's space but the sky's, seemingly divided by the pot's walls. Break the pot — the space was never divided. Advaita's image for the body-self relationship: the body is the pot; you are the space.", application: "The pot analogy is the library's most practical non-dual image. In any confinement — role, body, situation — remember the space was never confined. The walls are real; the confinement is the mistake.", questions: ["What pot am I mistaking for my boundary?", "Where do I feel confined that the space was never confined?", "What changes when the pot is seen as pot, not as space?"], references: ["Vivekachudamani 55-60", "Yoga Vasistha 2.2", "Ashtavakra Gita 11.1-11.10"], excerpt: "The pot's space is not the pot's space — it is the sky's, seemingly divided.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana"], domains: ["spirituality", "growth"], tags: ["advaita", "pot", "space", "vessel", "body", "confinement"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Mirror Analogy — The World Reflected", tradition: "Advaita Vedanta", source: "Vivekachudamani 105-110; Yoga Vasistha", explanation: "The mirror analogy: the world is reflected in the self, as the world is reflected in a mirror. The mirror is not stained by what it reflects; the self is not modified by the world. The analogy's precision: reflection without modification — the world is in the self as image, not as substance.", application: "The mirror teaching is the library's compassion foundation: the world's pain can be reflected without the self being stained. Compassion remains; contamination does not. The application is the distinction between reflection and absorption.", questions: ["What am I mistaking for stain — reflection or identification?", "How do I hold the world's pain without being stained by it?", "What is the difference between reflection and absorption?"], references: ["Vivekachudamani 105-110", "Yoga Vasistha 3.1", "Ashtavakra Gita 10.1-10.10"], excerpt: "The world is reflected in you, as in a mirror — the mirror is not stained.", evidence: "traditional", dimensions: ["spirit", "emotion"], paths: ["jnana"], domains: ["spirituality", "relationships"], tags: ["advaita", "mirror", "reflection", "unstained", "compassion", "absorption"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Ocean-Wave — You Are the Water", tradition: "Advaita Vedanta", source: "Yoga Vasistha; Vivekachudamani tradition", explanation: "The ocean-wave image: you are the ocean, not the waves. The waves rise and fall — thoughts, emotions, events — but the water is never harmed. The image's precision: the wave's drama is real as pattern, unreal as self. The water is not the wave's enemy; it is the wave's substance.", application: "In emotional weather, ask: am I the wave or the water? The answer is not to stop waving but to stop drowning in the wave's identity. The water allows the wave; the wave does not exhaust the water.", questions: ["Which wave am I currently identified with?", "What would 'being the water' feel like in this moment?", "Can the wave be allowed to wave, without me being it?"], references: ["Yoga Vasistha 2.2", "Vivekachudamani 110-115", "Ashtavakra Gita 9.1-9.10"], excerpt: "You are the ocean; the waves are your movements, not your identity.", evidence: "traditional", dimensions: ["spirit", "emotion"], paths: ["jnana"], domains: ["spirituality", "growth"], tags: ["advaita", "ocean", "wave", "water", "identity", "emotion"], difficulty: "beginner", minutes: 5 },
  { concept: "The Sky-Cloud — The Unaffected Witness", tradition: "Advaita Vedanta", source: "Ashtavakra Gita 17; Yoga Vasistha", explanation: "The sky-cloud image: you are the sky; the mind's contents are clouds. The sky is not affected by the clouds, not even by the storm. The image's gift: the storm is allowed; the sky is remembered. Not suppression — the storm is real; the sky is unaffected.", application: "The sky-cloud stance is the library's most portable equanimity practice. In any storm, practice the sky's stance: the clouds are real, the sky is unaffected. The application is not indifference but the accurate distinction between weather and sky.", questions: ["What storm is in my sky today?", "Can I feel the sky's unaffectedness while the storm rages?", "What is the difference between the sky's stance and denial?"], references: ["Ashtavakra Gita 17.1-17.10", "Yoga Vasistha 1.1", "Vivekachudamani 115-120"], excerpt: "You are the sky; the clouds are the mind. The storm does not touch the sky.", evidence: "traditional", dimensions: ["spirit", "emotion"], paths: ["jnana", "raja"], domains: ["spirituality", "health"], tags: ["advaita", "sky", "cloud", "storm", "unaffected", "equanimity"], difficulty: "beginner", minutes: 5 },
  { concept: "The Snake's Non-Existence — The Error's Status", tradition: "Advaita Vedanta", source: "Vivekachudamani 37-38; Shankara's commentaries", explanation: "Advaita's subtle point: the snake never existed — not as a lie, but as an error. The rope was always there; the snake was the rope's misapprehension. The error is real as experience (the fear was real), unreal as entity (no snake was ever present). This is the teaching's most precise epistemology.", application: "The error-status teaching is the library's answer to 'was the world ever real?': the world is real as experience, unreal as entity — like the snake. The application is the precision: neither dismissing the experience nor reifying it.", questions: ["What is my current snake — and what is its rope?", "Was the fear real — and was the snake?", "Can I hold 'real as experience, unreal as entity' without collapsing into either?"], references: ["Vivekachudamani 37-38", "Shankara's Brahma Sutra Bhashya 2.1.14", "Brahma Sutras 2.1.14"], excerpt: "The snake never existed. The fear was real; the snake was not.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["learning", "spirituality"], tags: ["advaita", "snake", "non_existence", "error", "epistemology", "precision"], difficulty: "advanced", minutes: 8 },
  { concept: "The Teaching's Conclusion — You Are Already That", tradition: "Advaita Vedanta", source: "Vivekachudamani 331-340; Ashtavakra Gita 18", explanation: "Advaita's conclusion: you are already brahman — not becoming, not achieving, not approaching. The teaching's entire apparatus — practices, studies, disciplines — exists to remove the misapprehension, not to produce the self. The self was never absent; only the misidentification was present.", application: "The conclusion is the library's final teaching and its first: every practice is a covering-removal, not a self-production. The application is the practices' reorientation — from acquisition to recognition, from becoming to being.", questions: ["What am I trying to produce that I already am?", "What is the difference between removing misapprehension and producing the self?", "Can the practices be held as covering-removal — and what changes if they are?"], references: ["Vivekachudamani 331-340", "Ashtavakra Gita 18.1-18.10", "Brihadaranyaka Upanishad 1.4.10"], excerpt: "You are already that. The practices remove misapprehension; they do not produce the self.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana"], domains: ["spirituality"], tags: ["advaita", "conclusion", "already", "recognition", "covering_removal", "being"], difficulty: "advanced", minutes: 9 },
];

export const WISDOM_SAMKHYA: WisdomArchetype[] = [
  { concept: "Purusha and Prakriti — The Two Fundamentals", tradition: "Samkhya", source: "Samkhya Karika 1-3; Ishvarakrishna", explanation: "Samkhya's foundational dualism: purusha (pure consciousness, the witness, inactive, unchanging) and prakriti (primordial matter, active, changing, unconscious). Everything manifest is prakriti; everything witnessed is purusha. The two are real, distinct, and never in contact — yet their proximity produces the world's appearance.", application: "Use the two fundamentals as the library's metaphysical frame: in every experience, distinguish the witnessed (prakriti — body, mind, world) from the witness (purusha). The distinction is not denial of the world but accurate location of the self.", questions: ["In my current experience, what is prakriti — the witnessed?", "What is purusha — the witness?", "What is the difference between distinguishing and separating?"], references: ["Samkhya Karika 1-3", "Samkhya Karika 4-10", "Bhagavad Gita 13.1-13.3"], excerpt: "Purusha is the witness, inactive, unchanging. Prakriti is the witnessed, active, changing.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana", "sankhya"], domains: ["learning", "spirituality"], tags: ["samkhya", "purusha", "prakriti", "dualism", "witness", "witnessed"], difficulty: "advanced", minutes: 9 },
  { concept: "The Three Gunas — Sattva, Rajas, Tamas", tradition: "Samkhya", source: "Samkhya Karika 11-13; Bhagavad Gita 14", explanation: "Samkhya's three modes of prakriti: sattva (clarity, light, harmony, knowledge), rajas (activity, passion, restlessness, desire), tamas (inertia, darkness, heaviness, delusion). All manifest phenomena — including every mental state — are guna mixtures. The gunas are the world's chemistry.", application: "The gunas are the library's daily diagnostic. Name the current mixture: is this state sattvic (clear), rajasic (agitated), or tamasic (heavy)? The naming begins the shift — you cannot change a mixture you cannot name.", questions: ["What is my current guna-mixture — and in what proportion?", "Which guna dominates my life this week?", "What is one sattvic choice available today?"], references: ["Samkhya Karika 11-13", "Bhagavad Gita 14.5-14.20", "Mahabharata, Bhagavad Gita"], excerpt: "Sattva — clarity. Rajas — activity. Tamas — inertia. All is guna mixture.", evidence: "traditional", dimensions: ["thought", "emotion", "body"], paths: ["sankhya", "jnana"], domains: ["learning", "growth"], tags: ["samkhya", "gunas", "sattva", "rajas", "tamas", "mixture", "diagnostic"], difficulty: "beginner", minutes: 7 },
  { concept: "The Twenty-Five Tattvas — Samkhya's Map", tradition: "Samkhya", source: "Samkhya Karika 22-38", explanation: "Samkhya's complete map of manifest reality: twenty-five tattvas — from prakriti (the root) through mahat (the great principle), ahamkara (the I-maker), the five subtle elements (sound, touch, form, taste, smell), the five gross elements (ether, air, fire, water, earth), the five sense organs, the five action organs, and the mind. The map is the tradition's gift: a complete anatomy of experience.", application: "Use the twenty-five as a completeness check: any experience can be located in the map — which tattva is speaking? The map's purpose is not cataloguing but locating: the self is not any tattva; it is the one tattva (purusha) that is not part of the map.", questions: ["Which tattva is speaking in my current state?", "Where is the self in the map — and why is it not listed?", "What does the map's completeness teach about experience's structure?"], references: ["Samkhya Karika 22-38", "Samkhya Karika 39-45", "Samkhya Sutras"], excerpt: "Twenty-five tattvas — from prakriti to earth. The self is not among them.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana", "sankhya"], domains: ["learning", "spirituality"], tags: ["samkhya", "tattvas", "twenty_five", "map", "anatomy", "prakriti"], difficulty: "advanced", minutes: 10 },
  { concept: "Mahat — The Great Principle", tradition: "Samkhya", source: "Samkhya Karika 22-23", explanation: "Mahat (the great principle) — also called buddhi (the intellect) — is the first tattva to emerge from prakriti. It is the principle of determination, discrimination, and cosmic order. In the individual, mahat is the intellect's capacity to decide, to know, to discriminate. It is the closest tattva to purusha — and the most easily mistaken for it.", application: "The mahat teaching is the library's intellectual foundation: the intellect is the closest organ to the self — and the most dangerous misidentification. The application is the discrimination: the intellect decides; the self witnesses the deciding.", questions: ["Where am I mistaking the intellect for the self?", "What is the difference between deciding and witnessing the deciding?", "How does mahat's proximity to purusha explain spiritual pride?"], references: ["Samkhya Karika 22-23", "Samkhya Karika 24-25", "Vivekachudamani 67-72"], excerpt: "Mahat — the great principle, the intellect, closest to purusha and most easily mistaken for it.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana", "sankhya"], domains: ["learning", "spirituality"], tags: ["samkhya", "mahat", "buddhi", "intellect", "discrimination", "great_principle"], difficulty: "advanced", minutes: 8 },
  { concept: "Ahamkara — The I-Maker", tradition: "Samkhya", source: "Samkhya Karika 24-26", explanation: "Ahamkara — the I-maker, the ego principle — is the tattva that manufactures 'I'. It takes the undifferentiated field of experience and divides it into 'me' and 'not-me'. Samkhya's precision: ahamkara is not the self but a function of prakriti — an organ, not the owner. It makes the I; it is not the I.", application: "The ahamkara teaching is the library's most practical: every 'I am' claim is ahamkara's product. The application is not to destroy the I-maker (impossible — it is an organ) but to see its products as products. The I is made; the maker is made; the witness is unmade.", questions: ["Where is ahamkara currently manufacturing an 'I'?", "What is the difference between the I-maker and the I it makes?", "Can the made I be used without being owned?"], references: ["Samkhya Karika 24-26", "Samkhya Karika 27-30", "Yoga Sutras 2.6"], excerpt: "Ahamkara — the I-maker. It makes the I; it is not the I.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana", "sankhya"], domains: ["learning", "growth"], tags: ["samkhya", "ahamkara", "ego", "i_maker", "manufactures", "organ"], difficulty: "intermediate", minutes: 7 },
  { concept: "Manas — The Coordinator", tradition: "Samkhya", source: "Samkhya Karika 27-29", explanation: "Manas — the mind-stuff — is Samkhya's eleventh organ, the coordinator. It receives the senses' reports, arranges them, passes them to buddhi, and executes buddhi's decisions. Samkhya's precision: manas is not the thinker but the arranging function — the desk, not the desk's occupant.", application: "The manas teaching corrects the modern confusion of mind with self. The application: when the mind is busy, ask what it is busy doing — arranging, coordinating, executing. The arranger is an organ; the occupant is the self.", questions: ["What is my manas currently arranging?", "Where am I mistaking the desk for its occupant?", "What is the difference between coordinating and knowing?"], references: ["Samkhya Karika 27-29", "Samkhya Karika 30-33", "Bhagavad Gita 3.5"], excerpt: "Manas — the coordinator. The desk, not the desk's occupant.", evidence: "traditional", dimensions: ["thought"], paths: ["jnana", "sankhya"], domains: ["learning"], tags: ["samkhya", "manas", "mind", "coordinator", "arranging", "organ"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Five Sense Organs — Jnanendriyas", tradition: "Samkhya", source: "Samkhya Karika 28-29", explanation: "Samkhya's five knowledge organs: hearing (ear), touching (skin), seeing (eye), tasting (tongue), smelling (nose). Each is a channel — not the sense itself but the aperture through which prakriti's data enters. The organs are prakriti's; the knowing is purusha's.", application: "The jnanendriya teaching is the library's sensory foundation: the senses are channels, not knowers. The application is the channel's care — what enters through the five channels becomes the mind's material. Curate the channels; the mind follows.", questions: ["Which of the five channels dominates my intake?", "What is entering through my channels — and what is its effect?", "Can I distinguish the channel from the knowing?"], references: ["Samkhya Karika 28-29", "Samkhya Karika 30-33", "Chandogya Upanishad 7.1"], excerpt: "Five knowledge organs — hearing, touching, seeing, tasting, smelling. Channels, not knowers.", evidence: "traditional", dimensions: ["body", "thought"], paths: ["sankhya", "jnana"], domains: ["learning", "health"], tags: ["samkhya", "jnanendriyas", "sense_organs", "channels", "intake", "curation"], difficulty: "beginner", minutes: 6 },
  { concept: "The Five Action Organs — Karmendriyas", tradition: "Samkhya", source: "Samkhya Karika 28-29", explanation: "Samkhya's five action organs: speech (mouth), grasping (hand), moving (feet), excreting (anus), reproducing (genitals). The organs of output — the channels through which prakriti's activity expresses. Samkhya's symmetry: five in, five out; the world is received and responded to.", application: "The karmendriya teaching is the library's action foundation: action is channeled through five organs. The application is the channel's ethics — what exits through the five channels is karma. Curate the output as carefully as the input.", questions: ["Which action organ is most active in my life?", "What is exiting through my channels — and what is its karma?", "Can I distinguish the channel from the actor?"], references: ["Samkhya Karika 28-29", "Samkhya Karika 30-33", "Bhagavad Gita 3.5-3.9"], excerpt: "Five action organs — speech, grasping, moving, excreting, reproducing. The channels of output.", evidence: "traditional", dimensions: ["action", "body", "thought"], paths: ["sankhya", "karma"], domains: ["learning", "ethics"], tags: ["samkhya", "karmendriyas", "action_organs", "output", "channels", "karma"], difficulty: "beginner", minutes: 6 },
  { concept: "The Five Subtle Elements — Tanmatras", tradition: "Samkhya", source: "Samkhya Karika 30-33", explanation: "Samkhya's five subtle elements (tanmatras): sound, touch, form, taste, smell — the raw sensory qualities before their grossification. The tanmatras are the world's data-structure: what the senses actually receive, before the mind names it. The teaching: experience begins as quality, not as object.", application: "The tanmatra teaching is the library's perception foundation: before the world is a 'tree', it is form; before it is 'music', it is sound. The application is the quality-first attention — perceive the tanmatra before the naming. The naming is the mind's addition.", questions: ["Can I perceive sound before it is 'a sound of something'?", "Where is my perception naming-first, quality-last?", "What is the difference between the quality and the object?"], references: ["Samkhya Karika 30-33", "Samkhya Karika 34-38", "Brihadaranyaka Upanishad 2.1"], excerpt: "Sound, touch, form, taste, smell — the subtle elements, before naming.", evidence: "traditional", dimensions: ["thought", "body"], paths: ["sankhya", "jnana"], domains: ["learning", "growth"], tags: ["samkhya", "tanmatras", "subtle_elements", "sound", "touch", "form", "quality"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Five Gross Elements — Mahabhutas", tradition: "Samkhya", source: "Samkhya Karika 34-38", explanation: "Samkhya's five gross elements (mahabhutas): ether (space), air, fire, water, earth — the tanmatras' grossification, the world's material structure. Each gross element carries the qualities of all five tanmatras (the doctrine of panchikarana — quintuplication). The world is not built from five separate materials but from five interpenetrating ones.", application: "The mahabhuta teaching is the library's cosmology: the world's material is interpenetrating, not separate. The application is ecological and perceptual — the elements are not 'out there' but the structure of every experience, including the body's.", questions: ["Where is the interpenetration visible in my current experience?", "What is the body's elemental structure — and what does it teach?", "Can I feel the five elements in one breath?"], references: ["Samkhya Karika 34-38", "Samkhya Karika 39-45", "Chandogya Upanishad 6.1-6.8"], excerpt: "Ether, air, fire, water, earth — quintuplicated, interpenetrating.", evidence: "traditional", dimensions: ["body", "thought", "spirit"], paths: ["sankhya", "hatha"], domains: ["learning", "health"], tags: ["samkhya", "mahabhutas", "gross_elements", "ether", "air", "fire", "water", "earth", "panchikarana"], difficulty: "intermediate", minutes: 8 },
  { concept: "The Evolution of Prakriti — Parinama", tradition: "Samkhya", source: "Samkhya Karika 21-38", explanation: "Samkhya's central cosmology: prakriti evolves (parinama) into the twenty-four tattvas — not by creation ex nihilo but by transformation, like milk into curd. The cause contains the effect; the effect is the cause's rearrangement. The evolution is driven by the gunas' disturbance and purusha's proximity (the 'spark' that starts the display).", application: "The parinama teaching is the library's systems view: nothing is created from nothing; everything is transformation. The application is the cause-effect discipline — trace any state to its guna-disturbance, and the transformation becomes workable.", questions: ["What is the cause of my current state — and what is its effect?", "Where is the guna-disturbance driving the transformation?", "What is the difference between creation and transformation?"], references: ["Samkhya Karika 21-38", "Samkhya Karika 9-10", "Yoga Sutras 2.18-2.19"], excerpt: "Prakriti evolves into the twenty-four tattvas — like milk into curd.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["sankhya", "jnana"], domains: ["learning", "spirituality"], tags: ["samkhya", "parinama", "evolution", "prakriti", "transformation", "cause_effect"], difficulty: "advanced", minutes: 9 },
  { concept: "The Three Gunas' Bondage — How They Bind", tradition: "Samkhya", source: "Samkhya Karika 11-13; Bhagavad Gita 14", explanation: "Samkhya's binding mechanism: the gunas bind purusha through their mutual grasping. Sattva binds through attachment to knowledge and pleasure; rajas through attachment to action and restlessness; tamas through attachment to inertia and delusion. The binding is not punishment but the gunas' nature — they grasp because grasping is their function.", application: "The binding teaching is the library's most precise diagnosis: identify which guna is binding you — through what attachment. The application is not to escape the gunas (impossible — they are prakriti's fabric) but to stop grasping through them.", questions: ["Which guna is binding me right now — through what attachment?", "What is the difference between the guna and its grasping?", "Can I stop grasping without escaping the gunas?"], references: ["Samkhya Karika 11-13", "Bhagavad Gita 14.5-14.10", "Samkhya Karika 14-20"], excerpt: "Sattva binds through knowledge, rajas through action, tamas through inertia.", evidence: "traditional", dimensions: ["thought", "emotion", "spirit"], paths: ["sankhya", "jnana"], domains: ["learning", "growth"], tags: ["samkhya", "gunas", "bondage", "grasping", "attachment", "binding"], difficulty: "advanced", minutes: 8 },
  { concept: "Kaivalya — Aloneness as Liberation", tradition: "Samkhya", source: "Samkhya Karika 63-69", explanation: "Samkhya's goal: kaivalya — aloneness. Not loneliness but the purusha's final recognition: it was never in contact with prakriti. The gunas, having displayed their play, return to their root. The purusha remains — alone, witness, unchanged. Samkhya's kaivalya is Advaita's brahman-realization stated in dualist vocabulary.", application: "The kaivalya teaching is the library's liberation horizon. The application is the recognition's practice: the gunas' play continues; the purusha's aloneness is not withdrawal but accuracy. The witness was never in the play.", questions: ["What is the difference between aloneness and loneliness?", "Where am I still claiming contact with prakriti as 'me'?", "What is the purusha's aloneness — and can it be recognized, not achieved?"], references: ["Samkhya Karika 63-69", "Yoga Sutras 4.34", "Samkhya Sutras"], excerpt: "Kaivalya — aloneness. The purusha was never in contact with prakriti.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["sankhya", "jnana"], domains: ["spirituality"], tags: ["samkhya", "kaivalya", "aloneness", "liberation", "purusha", "recognition"], difficulty: "advanced", minutes: 9 },
  { concept: "The Gunas' Return — Prakriti's Withdrawal", tradition: "Samkhya", source: "Samkhya Karika 68-69", explanation: "Samkhya's final image: at liberation, the gunas — having served their purpose — return to their root, like a lamp when the light is no longer needed. Prakriti withdraws; the play ends; the purusha remains. The image's precision: prakriti is not destroyed but unmanifested — the dance stops, the dancers are not killed.", application: "The withdrawal teaching is the library's final cosmology: the world is not a mistake to be destroyed but a dance to be completed. The application is the dance's dignity — participate fully, knowing the dancers return to their root.", questions: ["What is my relationship to the dance's ending?", "Can I participate fully while knowing the dancers return to their root?", "What is the difference between the dance stopping and the dancers being destroyed?"], references: ["Samkhya Karika 68-69", "Samkhya Karika 63-67", "Bhagavad Gita 8.18-8.19"], excerpt: "The gunas return to their root, like a lamp when the light is no longer needed.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["sankhya", "jnana"], domains: ["spirituality"], tags: ["samkhya", "gunas", "return", "withdrawal", "prakriti", "dance", "root"], difficulty: "advanced", minutes: 8 },
  { concept: "The Spark and the Display — Purusha's Proximity", tradition: "Samkhya", source: "Samkhya Karika 20-21", explanation: "Samkhya's subtle causation: prakriti evolves not by itself but in proximity to purusha — like a magnet near iron filings, or a lamp near a pot. The purusha is inactive, never the doer; yet its presence is the display's condition. The teaching's precision: the witness is not the cause of the world, but the world is not without the witness.", application: "The proximity teaching is the library's most subtle: the witness is not the doer, but the display happens in its light. The application is the doer-ship's release — act fully, knowing the acting is prakriti's, the witnessing is purusha's.", questions: ["Where am I claiming doer-ship that belongs to prakriti?", "What is the difference between the display's condition and the display's cause?", "Can I act fully while resting as the witness?"], references: ["Samkhya Karika 20-21", "Samkhya Karika 22-25", "Samkhya Sutras"], excerpt: "Prakriti evolves in proximity to purusha — like a lamp near a pot.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["sankhya", "jnana"], domains: ["learning", "spirituality"], tags: ["samkhya", "purusha", "proximity", "display", "spark", "doership", "witness"], difficulty: "advanced", minutes: 9 },
  { concept: "The Doctrine of Satkaryavada — The Effect Is in the Cause", tradition: "Samkhya", source: "Samkhya Karika 9-10", explanation: "Samkhya's epistemology of causation: satkaryavada — the effect pre-exists in the cause. The cloth is in the thread; the curd is in the milk. Nothing new is created; everything is rearrangement. The doctrine's precision: the effect is not the cause's opposite (as in Western creation) but its manifestation.", application: "The satkaryavada teaching is the library's patience foundation: what manifests was already present. The application is the seed-discipline — the current state is the past cause's effect; the future state is the present cause's effect. Tend the cause.", questions: ["What is the cause of my current effect?", "What seed am I tending — and what will it manifest?", "What is the difference between creation and manifestation?"], references: ["Samkhya Karika 9-10", "Samkhya Karika 11-15", "Nyaya and Vaisheshika debates"], excerpt: "The effect pre-exists in the cause. The cloth is in the thread; the curd is in the milk.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["sankhya", "jnana"], domains: ["learning", "growth"], tags: ["samkhya", "satkaryavada", "cause", "effect", "seed", "manifestation", "rearrangement"], difficulty: "advanced", minutes: 8 },
  { concept: "The Five Ignorances — Samkhya's Bondage Map", tradition: "Samkhya", source: "Samkhya Karika 49-52", explanation: "Samkhya's bondage map: the eight-fold ignorance — the self's identification with the intellect, the ego, the mind, the senses, and the elements — the twenty-four tattvas mistaken for the twenty-fifth. The bondage is not one error but a systematic mislocation: the self is placed in the map, and the map is mistaken for the self.", application: "The mislocation teaching is the library's diagnostic core: suffering is the self's mislocation in the map. The application is the relocation — not a new place but the recognition that the self was never in the map at all.", questions: ["Where in the map have I placed myself?", "What is the mislocation's current form — intellect, ego, body, role?", "What is the relocation — and can it be recognized rather than achieved?"], references: ["Samkhya Karika 49-52", "Samkhya Karika 53-60", "Yoga Sutras 2.17"], excerpt: "The twenty-four tattvas mistaken for the twenty-fifth. The self is mislocated in the map.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["sankhya", "jnana"], domains: ["learning", "growth"], tags: ["samkhya", "ignorance", "mislocation", "map", "twenty_four", "twenty_fifth", "relocation"], difficulty: "advanced", minutes: 9 },
  { concept: "The Eight-Fold Yoga of Samkhya — The Path's Structure", tradition: "Samkhya", source: "Samkhya Karika 49-52; Yoga Sutras parallel", explanation: "Samkhya's path structure (parallel to Patanjali's): the discrimination (viveka) between purusha and prakriti, cultivated through the knowledge of the tattvas, the gunas' mechanics, and the mislocation's recognition. The path is not practice-heavy but knowledge-heavy — the knowledge itself is the liberation.", application: "The Samkhya path is the library's intellectual spine: the practices serve the knowledge; the knowledge is the liberation. The application is the study's discipline — the tattvas are not trivia but the map's accuracy, and the map's accuracy is the relocation's instrument.", questions: ["Is my practice serving the knowledge — or replacing it?", "What is my current study's discipline?", "Can I hold the practices as instruments of the knowledge, not as its substitutes?"], references: ["Samkhya Karika 49-52", "Yoga Sutras 2.25-2.29", "Samkhya Sutras"], excerpt: "The discrimination between purusha and prakriti — the knowledge itself is the liberation.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["sankhya", "jnana"], domains: ["learning", "spirituality"], tags: ["samkhya", "path", "viveka", "discrimination", "knowledge", "liberation", "structure"], difficulty: "advanced", minutes: 9 },
  { concept: "The Gunas' Colors — The World's Chemistry", tradition: "Samkhya", source: "Samkhya Karika 11-13; Bhagavad Gita 14", explanation: "Samkhya's phenomenology: every experience has a guna-color. Sattva is white — light, clear, luminous. Rajas is red — active, hot, restless. Tamas is black — heavy, dark, inert. The world's chemistry is the gunas' mixture; the mind's states are the gunas' proportions.", application: "The color teaching is the library's most practical diagnostic: name the current state's color. The naming is not labeling but chemistry — the mixture's recognition is the mixture's first transformation.", questions: ["What color is my current state — white, red, or black?", "What is the mixture's proportion — and what is its cause?", "What would one degree of color-change look like today?"], references: ["Samkhya Karika 11-13", "Bhagavad Gita 14.5-14.10", "Mahabharata"], excerpt: "Sattva is white, rajas is red, tamas is black. The world's chemistry is the mixture.", evidence: "traditional", dimensions: ["thought", "emotion", "body"], paths: ["sankhya", "jnana"], domains: ["learning", "growth"], tags: ["samkhya", "gunas", "colors", "white", "red", "black", "chemistry", "mixture"], difficulty: "beginner", minutes: 6 },
  { concept: "The Mind's Eleven Organs — Samkhya's Complete Anatomy", tradition: "Samkhya", source: "Samkhya Karika 27-29", explanation: "Samkhya's complete anatomy: the mind (manas) plus ten organs — five knowledge organs (jnanendriyas) and five action organs (karmendriyas) — the eleven-fold inner instrument. The anatomy's precision: the mind is the eleventh, coordinating the ten. The self is not among the eleven — it is the twenty-fifth tattva, beyond the instrument.", application: "The eleven-organ anatomy is the library's completeness check: any experience can be located in the instrument. The application is the instrument's care — the ten channels' input and output, the coordinator's clarity, and the self's location beyond all.", questions: ["Which of the eleven organs is dominant in my current state?", "Where is the coordinator (manas) confused — and what is its cost?", "Can I locate the self beyond the instrument — not in it?"], references: ["Samkhya Karika 27-29", "Samkhya Karika 30-33", "Bhagavad Gita 3.5"], excerpt: "The mind plus ten organs — the eleven-fold instrument. The self is the twenty-fifth, beyond it.", evidence: "traditional", dimensions: ["thought", "body", "spirit"], paths: ["sankhya", "jnana"], domains: ["learning", "health"], tags: ["samkhya", "eleven_organs", "manas", "jnanendriyas", "karmendriyas", "anatomy", "instrument"], difficulty: "intermediate", minutes: 8 },
  { concept: "The Root and the Display — Prakriti's Dormant State", tradition: "Samkhya", source: "Samkhya Karika 11-13; 68-69", explanation: "Samkhya's cosmology of the root: before evolution, prakriti is dormant — the gunas in perfect equilibrium, unmanifest. The display begins with the equilibrium's disturbance (purusha's proximity as condition). At liberation, the gunas return to equilibrium — the display withdrawn, the root unchanged. The root was never the display; the display was never the root.", application: "The root-display teaching is the library's deepest patience lesson: the dormant state is not the absence of the manifest but its ground. The application is the equilibrium's recognition — in stillness, the gunas are not absent but balanced.", questions: ["What is my current equilibrium — and what disturbed it?", "Can I recognize the root beneath the display?", "What is the difference between the ground's stillness and the display's absence?"], references: ["Samkhya Karika 11-13", "Samkhya Karika 68-69", "Samkhya Sutras"], excerpt: "Before evolution, prakriti is dormant — the gunas in equilibrium. At liberation, they return.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["sankhya", "jnana"], domains: ["spirituality", "learning"], tags: ["samkhya", "prakriti", "root", "display", "equilibrium", "dormant", "ground"], difficulty: "advanced", minutes: 9 },
  { concept: "The Twenty-Four and the Twenty-Fifth — The Map's Missing One", tradition: "Samkhya", source: "Samkhya Karika 22-38; 63", explanation: "Samkhya's most precise teaching: the map has twenty-four tattvas — all prakriti's products — and the twenty-fifth (purusha) is not in the map. The self is not a tattva; it is the map's absence. The teaching's precision: everything you can locate is prakriti; what you cannot locate is purusha.", application: "The missing-one teaching is the library's neti-neti foundation: every located candidate is prakriti's; the self is the locator. The application is the subtraction — locate every candidate, subtract every one, and recognize what was never in the map.", questions: ["What candidates have I located in the map — and subtracted?", "What is the locator — and can it be located?", "What is the difference between the map's presence and the map's absence?"], references: ["Samkhya Karika 22-38", "Samkhya Karika 63", "Brihadaranyaka Upanishad 2.3.6"], excerpt: "Twenty-four tattvas in the map. The twenty-fifth is not in the map — it is the map's absence.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["sankhya", "jnana"], domains: ["learning", "spirituality"], tags: ["samkhya", "twenty_four", "twenty_fifth", "purusha", "map", "missing", "absence"], difficulty: "advanced", minutes: 9 },
  { concept: "Samkhya and Yoga — The Twin Traditions", tradition: "Samkhya", source: "Samkhya Karika; Yoga Sutras", explanation: "Samkhya and Yoga are twin traditions: Samkhya provides the map (the twenty-five tattvas, the gunas, the dualism), Yoga provides the method (the eight limbs, the practices, the discipline). Samkhya is the theory; Yoga is the practice. The traditions are so intertwined that Patanjali's Yoga Sutras are often called 'Samkhya with Ishvara'.", application: "The twin-tradition teaching is the library's architecture lesson: theory and method are partners, not rivals. The application is the pairing — every map entry (wisdom) is paired with its method entry (practice). This library's knowledge graph does exactly that.", questions: ["Where is my practice ahead of my theory — and where is my theory ahead of my practice?", "What is the map-method pairing for my current question?", "Can I hold Samkhya's map and Yoga's method as one tradition's two hands?"], references: ["Samkhya Karika", "Yoga Sutras 1.1-1.2", "Samkhya Sutras", "Bhagavad Gita 2.39"], excerpt: "Samkhya is the theory; Yoga is the practice. Twin traditions, one teaching.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["sankhya", "raja"], domains: ["learning", "spirituality"], tags: ["samkhya", "yoga", "twin", "theory", "method", "map", "pairing"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Liberation's Certainty — Samkhya's Promise", tradition: "Samkhya", source: "Samkhya Karika 63-69", explanation: "Samkhya's final promise: liberation is certain for the one who completes the discrimination. Not 'maybe' but 'certainly' — the karika's closing verses declare the purusha's aloneness as the teaching's guaranteed fruit. The certainty's basis: the discrimination is not a belief but a recognition, and recognition does not fail.", application: "The certainty teaching is the library's confidence foundation: the practices are not gambles but instruments of recognition. The application is the discipline's trust — the map is accurate, the method is reliable, the recognition is certain for the one who completes it.", questions: ["What is my practice's certainty — and what undermines it?", "Where is my discrimination incomplete — and what is its completion?", "Can I hold the teaching's certainty without the ego's certainty?"], references: ["Samkhya Karika 63-69", "Yoga Sutras 4.34", "Vivekachudamani 331-340"], excerpt: "Liberation is certain for the one who completes the discrimination. Recognition does not fail.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["sankhya", "jnana"], domains: ["spirituality", "growth"], tags: ["samkhya", "liberation", "certainty", "promise", "discrimination", "recognition"], difficulty: "advanced", minutes: 8 },
];
